  this.ahK = "\u0407\u0457 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u2014 \u0443 \u0446\u044c\u043e\u043c\u0443 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043a\u0443. \u0417\u0430\u043f\u0440\u043e\u0448\u0443\u0439\u0442\u0435 \u043b\u044e\u0434\u0435\u0439 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f\u043c \u0456\u0437 \u0440\u043e\u0437\u0434\u0456\u043b\u0443 \u00ab\u0417\u0430\u043f\u0440\u043e\u0441\u0438\u0442\u0438\u00bb \u0439 \u0432\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0441\u0432\u0456\u0439 \u0432\u043b\u0430\u0441\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a: \u00ab\u0420\u0430\u0445\u0443\u043d\u043a\u0438\u00bb, \u0434\u0430\u043b\u0456 \u00ab\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u0430\u0431\u043e \u0434\u043e\u0434\u0430\u0442\u0438 \u0449\u0435\u00bb.";
  this.aim = "\u0417\u0430\u043f\u0440\u043e\u0441\u0438\u0442\u0438";
  this.ain = "\u041d\u0430\u0434\u0456\u0448\u043b\u0456\u0442\u044c \u0446\u0435 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f \u0442\u043e\u043c\u0443, \u043a\u043e\u0433\u043e \u0445\u043e\u0447\u0435\u0442\u0435 \u0431\u0430\u0447\u0438\u0442\u0438 \u0432 \u0433\u0440\u043e\u043c\u0430\u0434\u0456. \u0412\u043e\u043d\u043e \u0432\u0456\u0434\u043a\u0440\u0438\u0432\u0430\u0454 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a \u043e\u0434\u0440\u0430\u0437\u0443 \u0432 \u0446\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456.";
  this.ahb = "\u0412\u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u0438 \u0432\u0430\u0441";
  this.ahB = "\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0438\u0442\u0438 \u0449\u0435 \u0440\u0430\u0437";
  this.alo = "\u0417\u0430\u0431\u0443\u0442\u0438 \u0446\u044e \u0437\u0430\u044f\u0432\u043a\u0443";
  this.akp = "\u0425\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u0438";
  this.aj6 = "\u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u0447\u0435\u043a\u0430\u0454";
  this.ah4 = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u0438";
  this.akn = "\u0412\u0456\u0434\u0445\u0438\u043b\u0438\u0442\u0438";
  this.ah6 = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u043e";
  this.ako = "\u0412\u0456\u0434\u0445\u0438\u043b\u0435\u043d\u043e";
  this.ajf = "\u041d\u0435 \u043f\u0440\u0438\u0439\u043d\u044f\u0442\u043e";
  this.ak4 = "\u0426\u0435 \u043c\u0456\u0441\u0446\u0435 \u0437\u0430\u0439\u043d\u044f\u0442\u0435: \u043e\u0431\u0435\u0440\u0456\u0442\u044c \u0456\u043d\u0448\u0435.";
  this.ak2 = "\u0423 \u043c\u0456\u0441\u0446\u0456 \u2014 \u0432\u0456\u0434 3 \u0434\u043e 40 \u043c\u0430\u043b\u0438\u0445 \u043b\u0430\u0442\u0438\u043d\u0441\u044c\u043a\u0438\u0445 \u043b\u0456\u0442\u0435\u0440, \u0446\u0438\u0444\u0440 \u0430\u0431\u043e \u0434\u0435\u0444\u0456\u0441\u0456\u0432; \u0432 \u043e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u043b\u0456\u0442\u0435\u0440\u0438.";
  this.aii = "\u0421\u044c\u043e\u0433\u043e\u0434\u043d\u0456 \u0437\u0432\u0456\u0434\u0441\u0438 \u0431\u0456\u043b\u044c\u0448\u0435 \u043d\u0435 \u043c\u043e\u0436\u043d\u0430 \u0441\u0442\u0432\u043e\u0440\u044e\u0432\u0430\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0438.";
  this.aig = "\u0422\u0443\u0442 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u0441\u0442\u0432\u043e\u0440\u044e\u0454 \u043d\u0435 \u043a\u043e\u0436\u0435\u043d: \u0437\u0432\u0435\u0440\u043d\u0456\u0442\u044c\u0441\u044f \u0434\u043e \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0446\u044c\u043e\u0433\u043e \u0441\u0430\u0439\u0442\u0443.";
  this.ah9 = "\u0406\u043d\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430";
  this.ala = "\u041e\u0434\u0438\u043d\u0438\u0446\u044f";
  this.ajR = "\u0414\u043e \u0456\u043d\u0448\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.all = "\u0414\u043e \u044f\u043a\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.aj9 = "\u0423 \u0442\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u043f\u043e\u043a\u0438 \u0449\u043e \u043d\u0456\u043a\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0438\u0442\u0438.";
  this.al3 = "\u041b\u0456\u043d\u0456\u0457 \u0434\u043e\u0432\u0456\u0440\u0438";
  this.aiE = "\u041b\u0456\u043d\u0456\u044f \u0434\u043e\u0432\u0456\u0440\u0438 \u043a\u0430\u0436\u0435, \u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0456\u043d\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0430 \u043d\u0430\u0448\u0456\u0439. \u0422\u043e\u0434\u0456 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043c\u043e\u0436\u0443\u0442\u044c \u043f\u043b\u0430\u0442\u0438\u0442\u0438 \u043d\u0430\u0448\u0438\u043c, \u0430 \u043d\u0430\u0448\u0456 \u2014 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430\u043c, \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0412\u041e\u041d\u0410 \u0434\u043e\u0432\u0456\u0440\u044f\u0454 \u043d\u0430\u043c. \u041f\u043b\u044e\u0441 \u043d\u0430 \u0431\u0430\u043b\u0430\u043d\u0441\u0456: \u0432\u0438\u043d\u043d\u0456 \u043c\u0438; \u043c\u0456\u043d\u0443\u0441: \u0432\u0438\u043d\u043d\u0456 \u043d\u0430\u043c.";
  this.akX = "\u041c\u043e\u0436\u0443\u0442\u044c \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0456 \u043d\u0430\u043c";
  this.aj2 = "\u043b\u0456\u043d\u0456\u0439 \u043f\u043e\u043a\u0438 \u0449\u043e \u043d\u0435\u043c\u0430\u0454";
  this.ajJ = "\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u043b\u0456\u043d\u0456\u044e";
  this.aiy = "\u0410\u0434\u0440\u0435\u0441\u0430 \u0456\u043d\u0448\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.aiz = "\u044f\u043a \u0443 \u0457\u0457 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u0456-\u0437\u0430\u043f\u0440\u043e\u0448\u0435\u043d\u043d\u0456 \u043f\u0456\u0441\u043b\u044f ?node=";
  this.ahz = "\u0417\u043c\u0456\u043d\u0438\u0442\u0438";
  this.aiB = "\u041b\u0456\u043d\u0456\u044e \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e";
  this.aiA = "\u041b\u0456\u043d\u0456\u044e \u043d\u0435 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e";
  this.aiD = "\u0422\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0440\u0430\u0445\u0443\u0454 \u0432 \u0456\u043d\u0448\u0456\u0439 \u043e\u0434\u0438\u043d\u0438\u0446\u0456: \u043b\u0456\u043d\u0456\u0457 \u043c\u0456\u0436 \u0440\u0456\u0437\u043d\u0438\u043c\u0438 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438 \u0449\u0435 \u043d\u0435 \u0437\u0440\u043e\u0431\u043b\u0435\u043d\u043e.";
  this.aj8 = "\u0417\u0430 \u0446\u0456\u0454\u044e \u0430\u0434\u0440\u0435\u0441\u043e\u044e \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043d\u0435 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0430\u0454.";
  this.aiC = "\u0426\u0435 \u0441\u0430\u043c\u0430 \u043d\u0430\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430.";
  this.alm = "\u0425\u0442\u043e \u043c\u043e\u0436\u0435 \u0432\u0441\u0442\u0443\u043f\u0438\u0442\u0438";
  this.ahp = "\u043b\u0438\u0448\u0435 \u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u0441\u0430\u043c\u043e\u0437\u0430\u0439\u043d\u044f\u0442\u0456 (\u043d\u0430\u0439\u043f\u0440\u043e\u0441\u0442\u0456\u0448\u0435)";
  this.ajT = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438, \u044f\u043a\u0456 \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u043b\u044f\u044e\u0442\u044c, \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u044e\u0442\u044c (\u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u043e\u0432\u0430\u043d\u043e)";
  this.ajS = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438, \u0432 \u0443\u0441\u0456\u0445 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0456 \u043b\u0456\u043d\u0456\u0457";
  this.ajM = "\u0412\u0430\u0448 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u043f\u043e\u0447\u0438\u043d\u0430\u0454\u0442\u044c\u0441\u044f \u0437 \u043d\u0443\u043b\u044f \u0439 \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f \u043d\u0435 \u043e\u043f\u0443\u0441\u043a\u0430\u0454\u0442\u044c\u0441\u044f. \u041f\u0440\u043e\u0434\u0430\u0439\u0442\u0435 \u0449\u043e\u0441\u044c \u0430\u0431\u043e \u0432\u0438\u043a\u043e\u043d\u0430\u0439\u0442\u0435 \u0440\u043e\u0431\u043e\u0442\u0443 \u0434\u043b\u044f \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430 \u2014 \u0456 \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0439\u0442\u0435 \u0437\u0430\u0440\u043e\u0431\u043b\u0435\u043d\u0435.";
  this.aj1 = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e\u0457 \u043e\u0441\u043e\u0431\u0438 \u0432 \u0446\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u043d\u0435 \u043c\u0430\u0454 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0457 \u043b\u0456\u043d\u0456\u0457: \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u0438\u0442\u0438, \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0442\u0438.";
  this.akt = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.aks = "\u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0438\u0439 \u0442\u0435\u043a\u0441\u0442: \u0439\u043e\u0433\u043e \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u043a\u043e\u0436\u0435\u043d \u043d\u043e\u0432\u0430\u0447\u043e\u043a. \u041f\u0435\u0440\u0448 \u043d\u0456\u0436 \u043d\u0430 \u043d\u044c\u043e\u0433\u043e \u043f\u043e\u043a\u043b\u0430\u0434\u0430\u0442\u0438\u0441\u044f, \u043f\u043e\u043a\u0430\u0436\u0456\u0442\u044c \u0439\u043e\u0433\u043e \u044e\u0440\u0438\u0441\u0442\u043e\u0432\u0456.";
  this.akN = "1. \u0413\u0440\u043e\u043c\u0430\u0434\u0430 \u0432\u0435\u0434\u0435 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0442\u043e\u0433\u043e, \u0449\u043e \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u0434\u0430\u044e\u0442\u044c \u043e\u0434\u043d\u0435 \u043e\u0434\u043d\u043e\u043c\u0443 \u0439 \u0431\u0435\u0440\u0443\u0442\u044c \u043e\u0434\u043d\u0435 \u0432 \u043e\u0434\u043d\u043e\u0433\u043e. \u041e\u0434\u0438\u043d\u0438\u0446\u044f \u2014 \u043c\u0456\u0440\u0430 \u0432 \u0446\u044c\u043e\u043c\u0443 \u0440\u0430\u0445\u0443\u043d\u043a\u0443; \u0443 \u0446\u0456\u043d\u0430\u0445 \u0432\u043e\u043d\u0430 \u0440\u0430\u0445\u0443\u0454\u0442\u044c\u0441\u044f \u044f\u043a \u043e\u0434\u043d\u0430 \u043e\u0434\u0438\u043d\u0438\u0446\u044f \u043d\u0430\u0446\u0456\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0457 \u0432\u0430\u043b\u044e\u0442\u0438.\n2. \u041e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u043d\u0435 \u0433\u0440\u043e\u0448\u0456. \u041d\u0456\u0445\u0442\u043e \u0439 \u043d\u0456\u043a\u043e\u043b\u0438 \u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u0454, \u043d\u0435 \u043a\u0443\u043f\u0443\u0454 \u0456 \u043d\u0435 \u043e\u0431\u043c\u0456\u043d\u044e\u0454 \u0457\u0445 \u043d\u0430 \u0433\u0440\u043e\u0448\u0456.\n3. \u0411\u0430\u043b\u0430\u043d\u0441 \u0432\u0438\u0449\u0435 \u043d\u0443\u043b\u044f \u043f\u043e\u043a\u0430\u0437\u0443\u0454, \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u0434\u0430\u0432 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0443\u0437\u044f\u0432; \u0431\u0430\u043b\u0430\u043d\u0441 \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f \u2014 \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0432\u0456\u043d \u0443\u0437\u044f\u0432 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0434\u0430\u0432, \u0456 \u043c\u0430\u0454 \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u0441\u0432\u043e\u0457\u043c\u0438 \u0442\u043e\u0432\u0430\u0440\u0430\u043c\u0438 \u0439 \u043f\u043e\u0441\u043b\u0443\u0433\u0430\u043c\u0438.\n4. \u041a\u043e\u0436\u0435\u043d \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u043c\u0430\u0454 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0443 \u043b\u0456\u043d\u0456\u044e \u0456 \u0441\u0442\u0435\u043b\u044e; \u0457\u0445 \u0437\u0430\u0434\u0430\u0454 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0439 \u043c\u043e\u0436\u0435 \u0437\u043c\u0456\u043d\u044e\u0432\u0430\u0442\u0438.\n5. \u0423\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u0433\u0440\u043e\u043c\u0430\u0434\u0430, \u0456 \u0432\u043e\u043d\u0430 \u0437\u043d\u0430\u0454 \u0457\u0445 \u0437\u0430 \u0441\u043f\u0440\u0430\u0432\u0436\u043d\u0456\u043c\u0438 \u0456\u043c\u0435\u043d\u0430\u043c\u0438.\n6. \u041f\u0440\u043e\u0434\u0430\u0436 \u0437\u0430 \u043e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u0446\u0435 \u043f\u0440\u043e\u0434\u0430\u0436. \u041a\u043e\u0436\u0435\u043d \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u0441\u0430\u043c \u0432\u0438\u0441\u0442\u0430\u0432\u043b\u044f\u0454 \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0439 \u0441\u0430\u043c \u0441\u043f\u043b\u0430\u0447\u0443\u0454 \u043f\u043e\u0434\u0430\u0442\u043a\u0438, \u0433\u0440\u043e\u0448\u0438\u043c\u0430, \u044f\u043a \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0443.\n7. \u0423\u0447\u0430\u0441\u043d\u0438\u043a \u043c\u043e\u0436\u0435 \u0432\u0438\u0439\u0442\u0438 \u0431\u0443\u0434\u044c-\u043a\u043e\u043b\u0438, \u0437\u0432\u0456\u0432\u0448\u0438 \u0431\u0430\u043b\u0430\u043d\u0441 \u0434\u043e \u043d\u0443\u043b\u044f. \u0422\u043e\u0439, \u0445\u0442\u043e \u0432\u0438\u0445\u043e\u0434\u0438\u0442\u044c \u0456\u0437 \u0431\u0430\u043b\u0430\u043d\u0441\u043e\u043c \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f, \u043f\u043e\u0433\u0430\u0448\u0430\u0454 \u0440\u0456\u0437\u043d\u0438\u0446\u044e \u0433\u0440\u043e\u0448\u0438\u043c\u0430 \u043f\u0440\u043e\u0442\u044f\u0433\u043e\u043c 30 \u0434\u043d\u0456\u0432.\n8. \u0413\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u043e\u0436\u0435 \u0437\u0430\u043a\u0440\u0438\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430, \u044f\u043a\u0438\u0439 \u043f\u043e\u0440\u0443\u0448\u0443\u0454 \u0446\u0456 \u043f\u0440\u0430\u0432\u0438\u043b\u0430.";
  this.agM = "\u041f\u0440\u0438\u0439\u043c\u0430\u044e";
  this.akq = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430";
  this.aku = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e";
  this.akr = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u0437\u043c\u0456\u043d\u0438\u043b\u0438\u0441\u044f: \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0456 \u043f\u0440\u0438\u0439\u043c\u0456\u0442\u044c \u0457\u0445 \u0437\u043d\u043e\u0432\u0443.";
  this.ajE = "\u0426\u044f \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u043b\u0438\u0448\u0435 \u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u0441\u0430\u043c\u043e\u0437\u0430\u0439\u043d\u044f\u0442\u0438\u0445.";
  this.ahO = "\u0421\u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438 \u0432\u0438\u043f\u0438\u0441\u043a\u0443 (CSV)";
  this.akO = "\u0421\u043a\u043e\u043f\u0456\u0439\u043e\u0432\u0430\u043d\u043e";
  this.akP = "\u0412\u0430\u0448\u0456 \u0443\u0433\u043e\u0434\u0438 \u0432 \u0431\u0443\u0444\u0435\u0440\u0456 \u043e\u0431\u043c\u0456\u043d\u0443 \u0443 \u0432\u0438\u0433\u043b\u044f\u0434\u0456 CSV: \u0432\u0441\u0442\u0430\u0432\u0442\u0435 \u0457\u0445 \u0443 \u0442\u0430\u0431\u043b\u0438\u0446\u044e \u0430\u0431\u043e \u043f\u0435\u0440\u0435\u0434\u0430\u0439\u0442\u0435 \u0431\u0443\u0445\u0433\u0430\u043b\u0442\u0435\u0440\u043e\u0432\u0456. \u0423\u0433\u043e\u0434\u0430 \u0432 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u0445 \u2014 \u0446\u0435 \u043f\u0440\u043e\u0434\u0430\u0436, \u0432\u0456\u043d \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f \u0439 \u043e\u043f\u043e\u0434\u0430\u0442\u043a\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f \u044f\u043a \u0431\u0443\u0434\u044c-\u044f\u043a\u0438\u0439 \u0456\u043d\u0448\u0438\u0439.";
  this.aji = "\u0426\u0435\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 \u043d\u0435 \u0434\u043e\u0437\u0432\u043e\u043b\u044f\u0454 \u0441\u0442\u043e\u0440\u0456\u043d\u0446\u0456 \u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438. \u0412\u0438\u0434\u0456\u043b\u0456\u0442\u044c \u0442\u0430\u0431\u043b\u0438\u0446\u044e \u0456 \u0441\u043a\u043e\u043f\u0456\u044e\u0439\u0442\u0435 \u0432\u0440\u0443\u0447\u043d\u0443.";
  this.aiF = "\u042f \u0432\u0442\u0440\u0430\u0442\u0438\u0432(\u043b\u0430) \u0441\u0432\u043e\u0457 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457";
  this.aiG = "\u041e\u0431\u0435\u0440\u0456\u0442\u044c \u0441\u0432\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a. \u0426\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u0441\u0442\u0432\u043e\u0440\u0438\u0442\u044c \u043d\u043e\u0432\u0438\u0439 \u043a\u043b\u044e\u0447 \u0456 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u0432\u0430\u0448\u0443 \u0433\u0440\u043e\u043c\u0430\u0434\u0443 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438, \u0449\u043e \u0446\u0435 \u0432\u0438. \u041f\u0456\u0441\u043b\u044f \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u043a\u043b\u044e\u0447 \u0442\u0440\u0438\u043c\u0430\u0442\u0438\u043c\u0435 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0447\u0435\u0440\u0435\u0437 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u2014 \u0447\u0430\u0441, \u0449\u043e\u0431 \u0432\u0438 \u0432\u0441\u0442\u0438\u0433\u043b\u0438 \u0432\u0456\u0434\u043c\u043e\u0432\u0438\u0442\u0438, \u044f\u043a\u0449\u043e \u043f\u0440\u043e\u0441\u0438\u0432 \u0445\u0442\u043e\u0441\u044c \u0456\u043d\u0448\u0438\u0439.";
  this.aip = "\u0426\u0435 \u043c\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.ahc = "\u0412\u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.ajw = "\u0429\u0435 \u043d\u0456: \u0441\u0442\u0440\u043e\u043a \u043e\u0447\u0456\u043a\u0443\u0432\u0430\u043d\u043d\u044f \u043d\u0435 \u043c\u0438\u043d\u0443\u0432.";
  this.ahh = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.ai5 = "\u0417\u0430\u0431\u0443\u0442\u0438";
  this.ahx = "\u0426\u0435 \u043d\u0435 \u044f: \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438";
  this.akl = "\u0421\u043a\u0430\u0441\u043e\u0432\u0430\u043d\u043e: \u0442\u043e\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u043e\u0442\u0440\u0438\u043c\u0430\u0454.";
  this.akj = "\u0425\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.aki = "\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0439\u0442\u0435, \u043b\u0438\u0448\u0435 \u044f\u043a\u0449\u043e \u0432\u043f\u0435\u0432\u043d\u0435\u043d\u0456, \u0449\u043e \u0446\u0435 \u0443\u0447\u0430\u0441\u043d\u0438\u043a: \u043f\u043e\u0433\u043e\u0432\u043e\u0440\u0456\u0442\u044c \u0456\u0437 \u043d\u0438\u043c, \u043d\u0435 \u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044e. \u0421\u0442\u0430\u0440\u0456 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u0449\u0435 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u043c\u043e\u0436\u0443\u0442\u044c \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438.";
  this.aj5 = "\u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u043f\u0440\u043e\u0441\u0438\u0442\u044c";
  this.ahM = "\u0426\u0435 \u0432\u0456\u043d (\u0432\u043e\u043d\u0430): \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438";
  this.akk = "\u041e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043e";
  this.ahW = "\u041d\u0435 \u0432\u0456\u043d (\u0432\u043e\u043d\u0430): \u0432\u0456\u0434\u0445\u0438\u043b\u0438\u0442\u0438";
  this.ahj = "\u0414\u043e\u0448\u043a\u0430";
  this.ahn = "\u0429\u043e \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u044e\u0442\u044c \u0456 \u0449\u043e \u0448\u0443\u043a\u0430\u044e\u0442\u044c. \u0426\u0456\u043d\u0430 \u2014 \u0432 \u043d\u0430\u0446\u0456\u043e\u043d\u0430\u043b\u044c\u043d\u0456\u0439 \u0432\u0430\u043b\u044e\u0442\u0456; \u0447\u0430\u0441\u0442\u043a\u0430 \u043a\u0430\u0436\u0435, \u044f\u043a\u0430 \u0457\u0457 \u0447\u0430\u0441\u0442\u0438\u043d\u0430 \u0431\u0435\u0440\u0435\u0442\u044c\u0441\u044f \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438, \u2014 \u0440\u0435\u0448\u0442\u0430 \u0441\u043f\u043b\u0430\u0447\u0443\u0454\u0442\u044c\u0441\u044f \u0433\u0440\u043e\u0448\u0438\u043c\u0430, \u043f\u043e\u0437\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u043e\u044e.";
  this.ahm = "\u0412\u0438\u0434";
  this.ajB = "\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0454";
  this.alj = "\u0448\u0443\u043a\u0430\u0454";
  this.ahk = "\u043f\u043e\u043a\u0438 \u0449\u043e \u043f\u043e\u0440\u043e\u0436\u043d\u044c\u043e: \u0431\u0443\u0434\u044c\u0442\u0435 \u043f\u0435\u0440\u0448\u0438\u043c";
  this.ajI = "\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438";
  this.agY = "\u041f\u0440\u043e\u043f\u043e\u043d\u0443\u044e";
  this.ah1 = "\u0428\u0443\u043a\u0430\u044e";
  this.ahZ = "\u0414\u043e\u043a\u043b\u0430\u0434\u043d\u0456\u0448\u0435";
  this.akd = "\u0426\u0456\u043d\u0430";
  this.ake = "\u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c: \u0437\u0430 \u0434\u043e\u043c\u043e\u0432\u043b\u0435\u043d\u0456\u0441\u0442\u044e";
  this.ahr = "\u0437\u0430 \u0434\u043e\u043c\u043e\u0432\u043b\u0435\u043d\u0456\u0441\u0442\u044e";
  this.aik = "\u041e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438, %";
  this.ail = "\u044f\u043a\u0443 \u0447\u0430\u0441\u0442\u043a\u0443 \u0446\u0456\u043d\u0438 \u0432\u0438 \u0431\u0435\u0440\u0435\u0442\u0435 \u0430\u0431\u043e \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438: 100 \u2014 \u0443\u0441\u044e, 50 \u2014 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443";
  this.akD = "\u0432\u0456\u0434 0 \u0434\u043e 100";
  this.akc = "\u041e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f \u043d\u0430 \u0434\u043e\u0448\u0446\u0456";
  this.ajn = "\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f";
  this.ahl = "\u041d\u0430 \u0434\u043e\u0448\u0446\u0456 \u043d\u0435\u043c\u0430\u0454 \u043c\u0456\u0441\u0446\u044f \u0434\u043b\u044f \u0449\u0435 \u043e\u0434\u043d\u043e\u0433\u043e \u0432\u0430\u0448\u043e\u0433\u043e \u043e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f: \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u043d\u0456\u043c\u0456\u0442\u044c \u043e\u0434\u043d\u0435.";
  this.akU = "\u0417\u043d\u044f\u0442\u0438 \u0437 \u0434\u043e\u0448\u043a\u0438";
  this.akE = "\u0421\u043f\u0456\u043b\u044c\u043d\u0456 \u0440\u0430\u0445\u0443\u043d\u043a\u0438";
  this.akK = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u0440\u043e\u0434\u0438\u043d\u0438 \u0447\u0438 \u043a\u043e\u043c\u0430\u043d\u0434\u0438 \u0442\u0440\u0438\u043c\u0430\u044e\u0442\u044c \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432, \u0430 \u043d\u0435 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457: \u043a\u043e\u0436\u0435\u043d \u0442\u0440\u0438\u043c\u0430\u0447 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0454\u0442\u044c\u0441\u044f \u043d\u0438\u043c \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u0441\u0432\u043e\u0433\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e, \u0430 \u0432\u0442\u0440\u0430\u0447\u0435\u043d\u0438\u0439 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u0437\u0430\u043c\u0456\u043d\u044e\u0454\u0442\u044c\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u2014 \u0443 \u0432\u043b\u0430\u0441\u043d\u043e\u043c\u0443 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u043b\u044e\u0434\u0438\u043d\u0438.";
  this.aj7 = "\u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0445 \u0440\u0430\u0445\u0443\u043d\u043a\u0456\u0432 \u043f\u043e\u043a\u0438 \u043d\u0435\u043c\u0430\u0454";
  this.aiV = "\u041d\u043e\u0432\u0438\u0439 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.akG = "\u041d\u0430\u0437\u0432\u0430";
  this.akH = "\u0421\u043f\u0435\u0440\u0448\u0443 \u0432\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0441\u0432\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a: \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0442\u0440\u0438\u043c\u0430\u044e\u0442\u044c \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0439\u043e\u0433\u043e \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432.";
  this.akJ = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e, \u0432\u0438 \u0439\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447. \u0412\u043b\u0430\u0441\u043d\u043e\u0457 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0457 \u043b\u0456\u043d\u0456\u0457 \u0432\u0456\u043d \u043d\u0435 \u043c\u0430\u0454: \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0454 \u0442\u0435, \u0449\u043e \u0439\u043e\u043c\u0443 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u043b\u0438, \u0430\u0431\u043e \u043b\u0456\u043d\u0456\u044e, \u044f\u043a\u0443 \u0439\u043e\u043c\u0443 \u043f\u043e\u0437\u0438\u0447\u0438\u0432 \u0443\u0447\u0430\u0441\u043d\u0438\u043a. \u0406\u043d\u0448\u0438\u0445 \u0434\u043e\u0434\u0430\u0439\u0442\u0435 \u0432 \u0440\u043e\u0437\u0434\u0456\u043b\u0456 \u00ab\u0422\u0440\u0438\u043c\u0430\u0447\u0456\u00bb.";
  this.aib = "\u0422\u0440\u0438\u043c\u0430\u0447\u0456";
  this.aic = "\u0425\u0442\u043e \u043c\u043e\u0436\u0435 \u0434\u0456\u044f\u0442\u0438 \u0432\u0456\u0434 \u0456\u043c\u0435\u043d\u0456 \u0446\u044c\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443: \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432, \u0443 \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u2014 \u0449\u043e \u0432\u0456\u043d \u043c\u043e\u0436\u0435 \u0456 \u0441\u043a\u0456\u043b\u044c\u043a\u0438. \u0422\u0440\u0438\u043c\u0430\u0447 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0454\u0442\u044c\u0441\u044f \u0440\u0430\u0445\u0443\u043d\u043a\u043e\u043c \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u0441\u0432\u043e\u0433\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e.";
  this.agX = "\u0414\u043e\u0434\u0430\u0442\u0438 \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.aia = "\u0423\u0447\u0430\u0441\u043d\u0438\u043a";
  this.alq = "\u0432\u0438";
  this.al6 = "\u0414\u0432\u0430 \u043f\u0456\u0434\u043f\u0438\u0441\u0438";
  this.al4 = "\u0414\u0432\u0430 \u0442\u0440\u0438\u043c\u0430\u0447\u0456 \u0434\u043b\u044f \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u043f\u043e\u043d\u0430\u0434";
  this.al5 = "\u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c: \u0434\u043b\u044f \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u0434\u043e\u0441\u0438\u0442\u044c \u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.al8 = "\u0412\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u043e";
  this.al7 = "\u0422\u0435\u043f\u0435\u0440 \u0434\u043b\u044f \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u0434\u043e\u0441\u0438\u0442\u044c \u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430.";
  this.al2 = "\u041f\u043b\u0430\u0442\u0435\u0436\u0456, \u0449\u043e \u0447\u0435\u043a\u0430\u044e\u0442\u044c \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.al1 = "\u041f\u043b\u0430\u0442\u0456\u0436 \u043f\u043e\u043d\u0430\u0434 \u043f\u043e\u0440\u0456\u0433 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0454 \u043e\u0434\u0438\u043d \u0442\u0440\u0438\u043c\u0430\u0447, \u0430 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u0456\u043d\u0448\u0438\u0439. \u041d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u0438\u0439 \u0437\u0430 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u043f\u043b\u0430\u0442\u0456\u0436 \u0432\u0456\u0434\u043f\u0430\u0434\u0430\u0454.";
  this.ajz = "\u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u0447\u0435\u043a\u0430\u0454";
  this.ahN = "\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438 \u0439 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u0438";
  this.akg = "\u0417\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0432\u0430\u0432";
  this.akf = "\u041f\u043b\u0430\u0442\u0456\u0436 \u0447\u0435\u043a\u0430\u0454 \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.aiP = "\u0426\u0435\u0439 \u043f\u043b\u0430\u0442\u0456\u0436 \u0437\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0432\u0430\u043b\u0438 \u0432\u0438: \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438 \u0439\u043e\u0433\u043e \u043c\u0430\u0454 \u0456\u043d\u0448\u0438\u0439 \u0442\u0440\u0438\u043c\u0430\u0447.";
  this.aiQ = "\u0426\u044c\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0435\u0436\u0443 \u043f\u043e\u0442\u0440\u0456\u0431\u0435\u043d \u0434\u0440\u0443\u0433\u0438\u0439 \u0442\u0440\u0438\u043c\u0430\u0447.";
  this.ak5 = "\u041f\u043e\u043b\u0456\u0442\u0438\u043a\u0430";
  this.akb = "\u0412\u043b\u0430\u0441\u043d\u0430 \u043f\u043e\u043b\u0456\u0442\u0438\u043a\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438: \u0434\u0456\u0454 \u0437 \u043c\u043e\u043c\u0435\u043d\u0442\u0443 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u0434\u043b\u044f \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443. \u041b\u0456\u043d\u0456\u0457, \u0432\u0438\u0434\u0430\u043d\u0456 \u0440\u0430\u043d\u0456\u0448\u0435, \u043b\u0438\u0448\u0430\u044e\u0442\u044c\u0441\u044f \u044f\u043a \u0454. \u0425\u0430\u0431, \u043d\u0430 \u044f\u043a\u043e\u043c\u0443 \u0441\u0442\u043e\u0457\u0442\u044c \u0433\u0440\u043e\u043c\u0430\u0434\u0430, \u043c\u043e\u0436\u0435 \u0434\u043e\u0437\u0432\u043e\u043b\u044f\u0442\u0438 \u043c\u0435\u043d\u0448\u0435, \u043d\u0456\u0436 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u044e\u0442\u044c \u0434\u0435\u0456\u043d\u0434\u0435.";
  this.ak7 = "\u0412\u0441\u0442\u0443\u043f \u0456 \u0431\u0456\u0437\u043d\u0435\u0441\u0438";
  this.ak8 = "\u041f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438";
  this.ak9 = "\u041a\u0440\u0435\u0434\u0438\u0442 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456\u0439 \u043e\u0441\u043e\u0431\u0456, \u043d\u0430\u0432\u0456\u0442\u044c \u0431\u0435\u0437\u0432\u0456\u0434\u0441\u043e\u0442\u043a\u043e\u0432\u0438\u0439, \u043c\u043e\u0436\u0435 \u043f\u0456\u0434\u043f\u0430\u0434\u0430\u0442\u0438 \u043f\u0456\u0434 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0441\u043f\u043e\u0436\u0438\u0432\u0447\u043e\u0433\u043e \u043a\u0440\u0435\u0434\u0438\u0442\u0443. \u0414\u0435 \u043b\u044e\u0434\u0438 \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u043b\u044f\u044e\u0442\u044c, \u0430 \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u044e\u0442\u044c, \u043a\u0440\u0435\u0434\u0438\u0442 \u043d\u0435 \u0432\u0438\u0434\u0430\u0454\u0442\u044c\u0441\u044f \u0456 \u043f\u0438\u0442\u0430\u043d\u043d\u044f \u043d\u0435 \u0432\u0438\u043d\u0438\u043a\u0430\u0454.";
  this.ajV = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438 \u2014 \u043b\u0438\u0448\u0435 \u0437 \u043b\u0456\u043d\u0456\u0454\u044e, \u044f\u043a\u0443 \u043f\u043e\u0437\u0438\u0447\u0438\u0432 \u0443\u0447\u0430\u0441\u043d\u0438\u043a";
  this.ajU = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438 \u2014 \u043b\u0456\u043d\u0456\u044f \u043f\u0456\u0441\u043b\u044f \u0442\u043e\u0433\u043e, \u044f\u043a \u043b\u044e\u0434\u0438\u043d\u0430 \u0437\u0430\u0440\u043e\u0431\u0438\u043b\u0430";
  this.ajW = "\u041a\u0440\u0435\u0434\u0438\u0442\u043d\u0430 \u043b\u0456\u043d\u0456\u044f \u043d\u043e\u0432\u043e\u0457 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e\u0457 \u043e\u0441\u043e\u0431\u0438";
  this.ajX = "\u0442\u0430\u043c, \u0434\u0435 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438 \u043c\u0430\u044e\u0442\u044c \u043b\u0456\u043d\u0456\u0457 \u0432\u0456\u0434 \u043f\u043e\u0447\u0430\u0442\u043a\u0443";
  this.ajY = "\u0421\u043a\u0456\u043b\u044c\u043a\u0438 \u0449\u043e\u043d\u0430\u0439\u0431\u0456\u043b\u044c\u0448\u0435 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0430 \u043b\u044e\u0434\u0438\u043d\u0430";
  this.ajZ = "\u0432\u043b\u0430\u0441\u043d\u0430 \u043b\u0456\u043d\u0456\u044f \u0439 \u043f\u043e\u0437\u0438\u0447\u0435\u043d\u0430 \u0440\u0430\u0437\u043e\u043c; \u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c: \u0431\u0435\u0437 \u043e\u0431\u043c\u0435\u0436\u0435\u043d\u043d\u044f";
  this.aiZ = "\u0431\u0435\u0437 \u043e\u0431\u043c\u0435\u0436\u0435\u043d\u043d\u044f";
